source experiment/env.sh && cat > tmp/gate-batch-2/gate-fns.sh <<'SH'
gate_summary () {                 # gate_summary <log-dir> <out-file>
    local L="$1" O="$2" R="$FORTRESS_HOME/ProjectFortress/TEST-RESULTS" f
    {
      printf '#suite\ttests\tfailures\terrors\tskipped\n'
      for f in "$R"/fast-*/TEST-*.txt "$R"/system-*/TEST-*.txt ; do
        [ -f "$f" ] || continue
        awk -v track="$(basename "$(dirname "$f")")" -F'[ ,:]+' '
          /^Testsuite:/ { n = split($2, p, "."); s = p[n] }
          /^Tests run:/ { print track "/" s "\t" $3 "\t" $5 "\t" $7 "\t" $9 ; exit }' "$f"
      done | sort
      for f in compileAll testFast testSystem ; do
        grep -h '^BUILD \|^Total time:' "$L/$f.txt" | sed "s|^|# $f: |"
      done
    } > "$O"
}

# repaired form, landed at climb-batch-workflow.js:809-822 (commit c766f6cc5): the
# system-<i> rows are one suite split by sorted index, so they are compared by their sum
gate_compare () {
    awk -F'\t' '
      function key(s) { sub("^system-[0-9]+/", "system/", s) ; return s }
      FNR == NR { if ($0 !~ /^#/ && NF == 5) base[key($1)] += $2 ; next }
      $0 !~ /^#/ && NF == 5 {
          k = key($1) ; seen[k] = 1 ; cur[k] += $2
          if ($3 + 0 > 0 || $4 + 0 > 0)              { print "RED\t" $1 "\t" $3 " failures, " $4 " errors" ; bad++ }
          if ($2 + 0 == 0)                           { print "EMPTY\t" $1 ; bad++ }
      }
      END { for (k in cur) if ((k in base) && cur[k] < base[k]) { print "COUNT DOWN\t" k "\t" base[k] " -> " cur[k] ; bad++ }
            for (s in base) if (!(s in seen)) { print "SUITE GONE\t" s "\t" base[s] " -> absent" ; bad++ }
            if (bad) exit 1 }' "$1" "$2"
}

# the pre-repair per-shard form, as the brief's text carries it, run as a cross-check
gate_compare_pershard () {
    awk -F'\t' '
      FNR == NR { if ($0 !~ /^#/ && NF == 5) base[$1] = $2 ; next }
      $0 !~ /^#/ && NF == 5 {
          seen[$1] = 1
          if (($1 in base) && $2 + 0 < base[$1] + 0) { print "COUNT DOWN\t" $1 "\t" base[$1] " -> " $2 ; bad++ }
          if ($3 + 0 > 0 || $4 + 0 > 0)              { print "RED\t" $1 "\t" $3 " failures, " $4 " errors" ; bad++ }
          if ($2 + 0 == 0)                           { print "EMPTY\t" $1 ; bad++ }
      }
      END { for (s in base) if (!(s in seen)) { print "SUITE GONE\t" s "\t" base[s] " -> absent" ; bad++ }
            if (bad) exit 1 }' "$1" "$2"
}

last_landed_summary () {
    git -C "$FORTRESS_HOME" log --name-only --pretty=format: -- \
        'explorations/compile-ladder/gate-baseline/summary.txt' \
        'explorations/compile-ladder/climb-batch-*/gate/summary.txt' | grep -m1 'summary.txt$'
}
SH
source tmp/gate-batch-2/gate-fns.sh && echo "last_landed_summary: $(last_landed_summary)" && gate_summary tmp/gate-batch-2 explorations/compile-ladder/climb-batch-2/gate/summary.txt && wc -l explorations/compile-ladder/climb-batch-2/gate/summary.txt && tail -8 explorations/compile-ladder/climb-batch-2/gate/summary.txt

